with expected(rule_id, seed_file, compute) as (values
  ('IN-LICENSURE-2026', 'sairncare_compliance_seed.json', '{"data": {"_corrected": "The working summary did not mention the grandfather clause, which is a real exemption from BOTH the degree and the experience requirement for directors already serving when the rule was adopted. Flagging an already-serving director as non-compliant would be a false finding.", "authority": {"citation": "410 IAC 16.2-5-1.3(l); IC 12-10-5.5 (Alzheimer''s and dementia special care disclosure)", "quote": "In facilities that are required under IC 12-10-5.5 to submit an Alzheimer''s and dementia special care unit disclosure form, the facility must designate a director for the Alzheimer''s and dementia special care unit. The director shall have an earned degree from an educational institution in a health care, mental health, or social service profession or be a licensed health facility administrator. The director shall have a minimum of one (1) year work experience with dementia or Alzheimer''s residents, or both, within the past five (5) years. Persons serving as a director for an existing Alzheimer''s and dementia special care unit at the time of adoption of this rule are exempt from the degree and experience requirements.", "read_on": "2026-08-22", "url": "https://www.in.gov/health/files/Residential_Care_Facility_Alzheimers_Rules.pdf"}, "base_license": "Residential Care Facility (410 IAC 16.2-5)", "director_requirements": {"experience_detail": "minimum one year work experience with dementia or Alzheimer''s residents, or both, within the past five years", "experience_window_years": 5, "experience_years": 1, "grandfathered": "Persons serving as a director for an existing Alzheimer''s and dementia special care unit at the time of adoption of this rule are exempt from the degree and experience requirements.", "qualification": "an earned degree from an educational institution in a health care, mental health, or social service profession, OR a licensed health facility administrator", "required_when": "the facility is required under IC 12-10-5.5 to submit an Alzheimer''s and dementia special care unit disclosure form"}, "disclosure_authority": "IC 12-10-5.5", "disclosure_required": true, "label": "Indiana — Residential Care Facility licence; memory care has no separate licence but requires a filed disclosure", "memory_care_license": null, "model": "single_license_plus_disclosure"}, "effective_from": "2011-06-14", "effective_to": null, "facility_class": "rcf", "requirement_type": "licensure", "state": "IN", "status": "active"}'::jsonb),
  ('IN-STAFFING-2026', 'sairncare_compliance_seed.json', '{"data": {"_corrected": "The working summary said Indiana has ''no numeric general staffing ratio''. That is wrong in a way that would have produced a false all-clear: Indiana has no per-RESIDENT ratio, but it does have real, enforceable NUMERIC threshold requirements keyed to census — a minimum awake staff person at all times, a nursing staff person once 50+ residents regularly receive nursing services or medication administration, and an additional nursing staff person for every further 50 residents above 100. Reporting ''no requirement'' here would tell a 120-resident facility it had nothing to meet.", "authority": {"citation": "410 IAC 16.2-5-1.4 (Residential care facilities: personnel)", "quote": "A minimum of one (1) awake staff person, with current CPR and first aid certificates, shall be on site at all times. ... If fifty (50) or more residents of the facility regularly receive residential nursing services or administration of medication, or both, at least one (1) nursing staff person shall be on site at all times. ... Residential facilities with over one hundred (100) residents regularly receiving residential nursing services or administration of medication, or both, shall have at least one (1) additional nursing staff person awake and on duty at all times for every additional fifty (50) residents.", "read_on": "2026-08-22", "url": "https://www.law.cornell.edu/regulations/indiana/410-IAC-16.2-5-1.4"}, "label": "Indiana — census-threshold staffing requirements", "method": "census_thresholds", "thresholds": [{"applies_when": "at all times", "must_be_awake": true, "must_hold": ["current CPR certificate", "current first aid certificate"], "requirement": "a minimum of one awake staff person on site", "staff_count": 1}, {"applies_when": "50 or more residents regularly receive residential nursing services or administration of medication, or both", "census_threshold": 50, "requirement": "at least one nursing staff person on site at all times", "staff_count": 1}, {"additional_staff_per_residents": 50, "applies_when": "over 100 residents regularly receive residential nursing services or administration of medication, or both", "census_threshold": 100, "must_be_awake": true, "requirement": "at least one additional nursing staff person awake and on duty at all times for every additional 50 residents"}]}, "effective_from": "2011-06-14", "effective_to": null, "facility_class": "rcf", "requirement_type": "staffing", "state": "IN", "status": "active"}'::jsonb),
  ('IN-TRAINING-2026', 'sairncare_compliance_seed.json', '{"data": {"authority": {"citation": "410 IAC 16.2-5-1.4 (staff) and 410 IAC 16.2-5-1.3(l) (SCU director)", "quote": "Staff who have contact with residents shall have a minimum of six (6) hours of dementia-specific training within six (6) months and three (3) hours annually thereafter to meet the needs or preferences, or both, of cognitively impaired residents effectively and to gain understanding of the current standards of care for residents with dementia.", "read_on": "2026-08-22", "url": "https://www.law.cornell.edu/regulations/indiana/410-IAC-16.2-5-1.4"}, "label": "Indiana — dementia-specific training", "purpose": "to meet the needs or preferences, or both, of cognitively impaired residents effectively and to gain understanding of the current standards of care for residents with dementia", "requirements": [{"annual_hours": 3, "initial_deadline": "within 6 months", "initial_hours": 6, "who": "staff who have contact with residents"}, {"annual_hours": 6, "initial_deadline": "within 3 months of initial employment as director", "initial_hours": 12, "who": "director of the Alzheimer''s and dementia special care unit"}], "structure": "initial_deadline_plus_annual_hours", "unverified": ["A shorter 30-day initial deadline for personnel specifically assigned to an Alzheimer''s and dementia special care unit appears in secondary sources but could not be confirmed against the primary rule text in this pass. NOT encoded — the confirmed 6-month deadline is used, and this note exists so the stricter deadline is checked before anyone relies on the looser one for SCU staff."]}, "effective_from": "2011-06-14", "effective_to": null, "facility_class": "rcf", "requirement_type": "training", "state": "IN", "status": "active"}'::jsonb),
  ('MI-LICENSURE-2026', 'sairncare_compliance_seed.json', '{"data": {"authority": {"citation": "MCL 333.20106 (home for the aged definition); Michigan LARA licensing rules for AFC small group homes (R 400.14xxx) and large group homes (R 400.15xxx)", "quote": "A ''home for the aged'' is a supervised personal care facility ... that provides room, board, and supervised personal care to 21 or more unrelated, nontransient individuals 55 years of age or older.", "read_on": "2026-08-22", "url": "https://www.legislature.mi.gov/Laws/MCL?objectName=MCL-333-20106"}, "label": "Michigan — no ''assisted living'' licence exists; Home for the Aged or Adult Foster Care", "license_classes": [{"capacity": "21 or more unrelated nontransient individuals aged 55+", "class": "home_for_the_aged", "note": "supervised personal care; no numeric staffing ratio in rule"}, {"capacity": "12 or fewer residents", "class": "afc_small_group"}, {"capacity": "13 to 20 residents", "class": "afc_large_group"}], "memory_care_license": null, "model": "no_assisted_living_license", "notes": ["There is no separate memory-care licence in Michigan. A facility marketing specialised Alzheimer''s or dementia care is subject to disclosure requirements covering its staff training and continuing-education policies, but the state does not set the hours.", "Adult Foster Care small-group licences also cover 1-6 resident homes; the staffing rule cited here is the small-group rule that governs homes of 12 or fewer."]}, "effective_from": "1994-05-24", "effective_to": null, "facility_class": null, "requirement_type": "licensure", "state": "MI", "status": "active"}'::jsonb),
  ('MI-STAFFING-AFC-LARGE-1994', 'sairncare_compliance_seed.json', '{"data": {"_corrected": "The working summary gave a single statewide AFC floor of 1 direct-care worker per 12 residents. That figure is the SMALL group home rule only. Large group homes are 1:15 during waking hours and 1:20 during normal sleeping hours — a different number AND shift-dependent, which the flat figure hides entirely. Applying 1:12 to a large home would over-state the requirement; applying it without the shift split would mis-state it in both directions.", "authority": {"citation": "R 400.15206 (Licensing rules for adult foster care large group homes, 13-20), eff. May 24, 1994", "quote": "The ratio of direct care staff to residents shall be adequate as determined by the department, to carry out the responsibilities defined in the act and in these rules and shall not be less than 1 direct care staff to 15 residents during waking hours or less than 1 direct care staff member to 20 residents during normal sleeping hours.", "read_on": "2026-08-22", "url": "https://www.michigan.gov/-/media/Project/Websites/lara/bchs/Folder3/BCAL_PUB-334_7_15_-_for_web.pdf"}, "exclusion": "Any individual, including a volunteer, is not counted toward the ratio unless the individual meets the qualifications of a direct care staff member.", "label": "Michigan — Adult Foster Care large group home (13-20) direct-care staffing", "method": "fixed_ratio_by_shift", "shifts": [{"per_residents": 15, "shift": "waking", "staff": 1}, {"note": "normal sleeping hours", "per_residents": 20, "shift": "sleeping", "staff": 1}]}, "effective_from": "1994-05-24", "effective_to": null, "facility_class": "afc_large_group", "requirement_type": "staffing", "state": "MI", "status": "active"}'::jsonb),
  ('MI-STAFFING-AFC-SMALL-1994', 'sairncare_compliance_seed.json', '{"data": {"authority": {"citation": "R 400.14206 (Licensing rules for adult foster care small group homes, 12 or less), eff. May 24, 1994", "quote": "The ratio of direct care staff to residents shall be adequate as determined by the department, to carry out the responsibilities defined in the act and in these rules and shall not be less than 1 direct care staff to 12 residents and children who are under the age of 12 years.", "read_on": "2026-08-22", "url": "https://www.michigan.gov/-/media/Project/Websites/lara/bchs/Folder3/BCAL_PUB-333_7_15_-_for_web_2.pdf"}, "exclusion": "Any individual, including a volunteer, is not counted toward the ratio unless the individual meets the qualifications of a direct care staff member.", "label": "Michigan — Adult Foster Care small group home (12 or fewer) direct-care staffing", "method": "fixed_ratio", "per_residents": 12, "shift_dependent": false, "staff": 1}, "effective_from": "1994-05-24", "effective_to": null, "facility_class": "afc_small_group", "requirement_type": "staffing", "state": "MI", "status": "active"}'::jsonb),
  ('MI-TRAINING-2026', 'sairncare_compliance_seed.json', '{"data": {"authority": {"citation": "Michigan LARA adult foster care licensing rules — reviewed for any dementia-specific training hour requirement; none present", "quote": "Reviewed the LARA large- and small-group-home licensing rule publications for any dementia-specific or Alzheimer''s-specific training hour mandate; the rules set staffing ratios and general training obligations but prescribe no dementia-specific hour requirement.", "read_on": "2026-08-22", "url": "https://www.michigan.gov/-/media/Project/Websites/lara/bchs/Folder3/BCAL_PUB-334_7_15_-_for_web.pdf"}, "label": "Michigan — no state-mandated dementia-training hour requirement", "notes": ["Michigan sets no dementia-specific training HOUR requirement for AFC homes or homes for the aged. This is a genuine substantive difference from OH, IN and PA, not a gap in this seed.", "Training content and hours are the facility''s own responsibility, established through its program statement and staff training policies; a facility that markets specialised dementia care must disclose its training and continuing-education practices.", "Because the state sets no floor, this app reports the requirement as facility-defined and will not invent an hour figure. A facility-defined target may be recorded locally and tracked against, but it is labelled as the facility''s own, never as a state mandate."], "state_mandated_dementia_hours": null, "structure": "no_state_mandated_hours"}, "effective_from": "1994-05-24", "effective_to": null, "facility_class": null, "requirement_type": "training", "state": "MI", "status": "active"}'::jsonb),
  ('OH-LICENSURE-MEMCARE-2024', 'sairncare_compliance_seed.json', '{"data": {"authority": {"citation": "OAC 173-39-02.16 (ODA provider certification: assisted living service), eff. July 1, 2024", "quote": "Certification types: ODA certifies each provider for either of the following: (1) The basic service. (2) The basic service and memory care.", "read_on": "2026-08-22", "url": "https://codes.ohio.gov/ohio-administrative-code/rule-173-39-02.16"}, "base_license": "Residential Care Facility (RCF) licence", "certification_types": ["basic service", "basic service and memory care"], "label": "Ohio — memory care is an ODA certification layered on the RCF licence, not a separate licence", "memory_care_definition": "A service provided to an individual whom a practitioner assessed and then issued a documented diagnosis of any form of dementia.", "model": "certification_layered_on_license", "notes": ["ODA certifies a provider for either the basic service, or the basic service AND memory care. There is no standalone memory-care licence.", "A documented practitioner diagnosis of dementia is part of the definition of the service itself, not merely an admission formality.", "Separately, the provider must assist an individual who calls through the resident call system, in person, in fewer than ten minutes."]}, "effective_from": "2024-07-01", "effective_to": null, "facility_class": "rcf_memory_care", "requirement_type": "licensure", "state": "OH", "status": "active"}'::jsonb),
  ('OH-STAFFING-MEMCARE-2024', 'sairncare_compliance_seed.json', '{"data": {"_corrected": "The working summary gave TWO branches (20% uplift, or 1:10 if memory-care-only). The rule has THREE, and the 1:10 is the last-resort fallback rather than the memory-care-only rule: a memory-care-only provider must use 20% above the MEDICAID-PROGRAM BENCHMARK AVERAGE whenever that average is readily available, and only falls back to 1:10 when it is not. Encoding 1:10 as the memory-care-only rule would under-staff any provider that can obtain the benchmark.", "authority": {"citation": "OAC 173-39-02.16(D)(3), eff. July 1, 2024", "quote": "(a) The provider has a sufficient number of RNs or LPNs on call or on site at all times for individuals receiving memory care. (b) The provider maintains the appropriate direct-care staff-to-resident ratio below for its memory care: (i) If providing memory care and the basic service at the same time, a ratio for the provider''s memory care that is at least twenty per cent higher than the provider''s ratio for its basic service. (ii) If providing only memory care and the average ratio for the basic service provided by a representative sample of providers participating in the medicaid-funded component of the assisted living program is readily available to the provider, then a ratio that is at least twenty per cent higher than that average ratio. (iii) If providing only memory care and the average ratio ... is not readily available to the provider, then a ratio of at least one direct-care staff member for every ten individuals receiving memory care with at least one direct-care staff member on each floor of the RCF if the RCF provides memory care on multiple floors.", "read_on": "2026-08-22", "url": "https://codes.ohio.gov/ohio-administrative-code/rule-173-39-02.16"}, "branches": [{"rule": "uplift_over_own_basic_ratio", "uplift_percent": 20, "when": "providing memory care and the basic service at the same time"}, {"benchmark": "average basic-service ratio of a representative sample of providers participating in the medicaid-funded component of the assisted living program", "rule": "uplift_over_benchmark_average", "uplift_percent": 20, "when": "providing only memory care AND the benchmark average ratio is readily available"}, {"additional": "at least one direct-care staff member on each floor of the RCF if memory care is provided on multiple floors", "per_residents": 10, "rule": "fixed_ratio", "staff": 1, "when": "providing only memory care AND the benchmark average is NOT readily available"}], "clinical_coverage": "A sufficient number of RNs or LPNs on call OR on site at all times for individuals receiving memory care.", "label": "Ohio — memory care direct-care staffing", "method": "percentage_uplift_with_fallback"}, "effective_from": "2024-07-01", "effective_to": null, "facility_class": "rcf_memory_care", "requirement_type": "staffing", "state": "OH", "status": "active"}'::jsonb),
  ('OH-TRAINING-2024', 'sairncare_compliance_seed.json', '{"data": {"_corrected": "The working summary said only ''initial + annual, curriculum specified in rule'' with no hours. Real hour figures exist, they live in the Department of Health rule (OAC 3701-16-06) rather than the ODA certification rule, and they STACK in a specific way that matters: the dementia-population hours may be counted toward the general annual requirement rather than being purely additive. That is the opposite of Pennsylvania, where the dementia hours are expressly IN ADDITION to the general hours.", "authority": {"citation": "OAC 3701-16-06(E) (residential care facility staff training); topic list from OAC 173-39-02.16(D)(4)", "quote": "(3) ... staff members employed by a residential care facility ... that admits or retains residents with late-stage cognitive impairment ... are obligated to have: (a) Two hours of initial training in the care of such residents within fourteen days of the first day of work; and (b) Four hours of continuing education in the care of such residents annually. The four hours of continuing education may count towards the continuing education obligated by paragraph (E)(7) of this rule. ... (7) Successfully complete at least eight hours of continuing education annually.", "read_on": "2026-08-22", "url": "https://codes.ohio.gov/ohio-administrative-code/rule-3701-16-06"}, "label": "Ohio — RCF staff training, including cognitive-impairment population hours", "memory_care_initial_topics": ["Overview of dementia: symptoms, treatment approaches, and progression", "Foundations of effective communication in dementia care", "Common behavior challenges specific to dementia and recommended behavior management techniques", "Current best practices in dementia care", "Missing resident prevention and response"], "requirements": [{"annual_hours": 4, "counts_toward_general_annual": true, "initial_deadline": "within 14 days of the first day of work", "initial_hours": 2, "stacking": "counts_toward_general", "who": "staff serving residents with late-stage cognitive impairment, or cognitive impairment with increased emotional needs or presenting behaviors"}, {"annual_hours": 8, "counts_toward_general_annual": true, "initial_deadline": "within 14 days of the first day of work", "initial_hours": 4, "note": "divided in equal proportions for each population", "stacking": "counts_toward_general", "who": "staff serving BOTH the cognitive-impairment population and residents with serious mental illness"}, {"annual_hours": 8, "who": "all staff — general continuing education"}, {"annual_hours": 9, "note": "in gerontology, health care, business administration, or residential care facility operation", "who": "administrator"}], "structure": "initial_plus_annual_hours_with_stacking"}, "effective_from": "2024-07-01", "effective_to": null, "facility_class": "rcf", "requirement_type": "training", "state": "OH", "status": "active"}'::jsonb),
  ('PA-LICENSURE-2026', 'sairncare_compliance_seed.json', '{"data": {"_corrected": "Corrected 2026-08-23. The special_care_unit block below originally declared available_under: [''pch'',''alr''] while every figure, phrase and citation in it is Chapter 2800 (ALR). Chapter 2600 does have an analogous unit, but it is a differently-named, differently-scoped, differently-routed thing (see PA-LICENSURE-PCH-2600), so this block is now scoped to ALR only. It was never a wrong FACT — it was a correct fact with too wide a claimed reach, which is the harder kind to spot.", "authority": {"citation": "55 Pa. Code §§ 2800.231 and 2800.239 (special care units; application to Department)", "quote": "The legal entity shall submit an application to the Department at least 60 days prior to the following: (1) Opening a special care unit. (2) Adding a special care unit to an existing residence. (3) Increasing the maximum capacity in an existing unit. (4) Changing the locking system, exit doors or floor plan of an existing unit.", "read_on": "2026-08-22", "url": "https://www.pacodeandbulletin.gov/Display/pacode?file=%2Fsecure%2Fpacode%2Fdata%2F055%2Fchapter2800%2Fchap2800toc.html"}, "label": "Pennsylvania — two parallel licences under different chapters", "license_classes": [{"chapter": "55 Pa. Code Ch. 2600", "class": "pch", "name": "Personal Care Home"}, {"chapter": "55 Pa. Code Ch. 2800", "class": "alr", "name": "Assisted Living Residence"}], "model": "two_parallel_licenses", "special_care_unit": {"application_lead_days": 60, "application_required_for": ["opening a special care unit", "adding a special care unit to an existing residence", "increasing the maximum capacity in an existing unit", "changing the locking system, exit doors or floor plan of an existing unit"], "available_under": ["alr"], "definition": "A residence or portion of a residence providing specialized care and services for residents with Alzheimer''s disease or dementia, and/or intense neurobehavioral rehabilitation for residents with severely disruptive and potentially dangerous behaviors as a result of brain injury.", "department_approval": "The Department will inspect and approve the special care unit prior to operation or change.", "name": "Special care unit", "pch_equivalent": "Chapter 2600 homes have a SECURED DEMENTIA CARE UNIT instead — dementia only, requested through the personal care home regional office. Its rules are in PA-LICENSURE-PCH-2600 and are not interchangeable with these."}}, "effective_from": "2010-10-01", "effective_to": null, "facility_class": null, "requirement_type": "licensure", "state": "PA", "status": "active"}'::jsonb),
  ('PA-LICENSURE-PCH-2600', 'sairncare_compliance_seed.json', '{"data": {"_corrected": "Until this rule existed, a PCH facility asking about licensure fell through to the class-agnostic PA-LICENSURE-2026 rule, whose special_care_unit block is quoted verbatim from Chapter 2800 (ALR) while asserting available_under: [''pch'',''alr'']. The two chapters are NOT interchangeable here. Chapter 2800 calls it a SPECIAL CARE UNIT and its definition covers both dementia AND intense neurobehavioral rehabilitation after brain injury; Chapter 2600 calls it a SECURED DEMENTIA CARE UNIT and covers dementia only. The 2800 route is an application to the Department; the 2600 route is a written request to the Department''s personal care home REGIONAL OFFICE. Both carry the same 60-day lead time and the same four triggering events, which is precisely what made the substitution look harmless.", "authority": {"citation": "55 Pa. Code §§ 2600.231(a)—(c), 2600.231(e)—(g), 2600.239(a)—(c) (secured dementia care units), adopted eff. October 24, 2005", "quote": "§ 2600.231(a): This section and §§ 2600.232—2600.239 apply to secured dementia care units. These provisions are in addition to the other provisions of this chapter. A secured dementia care unit is a home or portion of a home that provides specialized care and services for residents with Alzheimer''s disease or other dementia. ... (c) A written cognitive preadmission screening completed in collaboration with a physician or a geriatric assessment team and documented on the Department''s preadmission screening form shall be completed for each resident within 72 hours prior to admission to a secured dementia care unit. ... § 2600.239(a): The legal entity shall submit a written request to the Department''s personal care home regional office at least 60 days prior to the following: (1) Opening a secured care dementia unit. (2) Adding a secured dementia care unit to an existing home. (3) Increasing the maximum capacity in an existing unit. (4) Changing the locking system, exit doors or floor plan of an existing unit.", "read_on": "2026-08-23", "url": "https://www.pacodeandbulletin.gov/Display/pacode?file=/secure/pacode/data/055/chapter2600/s2600.231.html"}, "base_license": "Personal Care Home licence (55 Pa. Code Ch. 2600)", "label": "Pennsylvania — Personal Care Home licence, and the secured dementia care unit that sits inside it", "memory_care_license": false, "model": "standalone_license_with_optional_secured_unit", "notes": ["PCH is a standalone licence class, not a certification layered on another licence (contrast Ohio) and not an absent category (contrast Michigan).", "The secured dementia care unit is a unit WITHIN a personal care home, governed by §§ 2600.231—2600.239 in addition to — never instead of — the rest of Chapter 2600.", "This rule answers the PCH question specifically. The class-agnostic PA-LICENSURE-2026 rule still answers ''which licences does Pennsylvania issue'', and remains correct for that; the engine''s exact-class preference means a facility that states pch now gets this rule instead of Chapter 2800''s numbers."], "special_care_unit": {"annual_reassessment": "In addition to the § 2600.225 initial and annual assessment, the resident shall be assessed annually for the CONTINUING need for the secured dementia care unit.", "application_lead_days": 60, "application_required_for": ["opening a secured dementia care unit", "adding a secured dementia care unit to an existing home", "increasing the maximum capacity in an existing unit", "changing the locking system, exit doors or floor plan of an existing unit"], "application_route": "A written request to the Department''s personal care home regional office, not the Chapter 2800 application process.", "available_under": ["pch"], "definition": "A home or portion of a home that provides specialized care and services for residents with Alzheimer''s disease or other dementia.", "department_approval": "The Department will inspect and approve the secured dementia care unit prior to operation or change. The requirements of the chapter shall be met prior to operation.", "name": "Secured dementia care unit", "preadmission": {"cognitive_screening_by": "completed in collaboration with a physician or a geriatric assessment team, on the Department''s preadmission screening form", "cognitive_screening_within_hours_prior": 72, "medical_evaluation_by": "physician, physician''s assistant or certified registered nurse practitioner, documented on a Department form, including the diagnosis of Alzheimer''s disease or other dementia and the need to be served in a secured unit", "medical_evaluation_within_days_prior": 60, "no_objection_documented": "Each resident record must document that the resident and the resident''s designated person have not objected to the admission or transfer to the secured unit."}, "resident_without_dementia_diagnosis": "May reside in the unit if the resident wishes, but must be able to operate the key pads or other lock-releasing devices to exit.", "scope_note": "Dementia only. Unlike the Chapter 2800 special care unit, this does not extend to intense neurobehavioral rehabilitation after brain injury.", "written_request_document_count": 22}}, "effective_from": "2005-10-24", "effective_to": null, "facility_class": "pch", "requirement_type": "licensure", "state": "PA", "status": "active"}'::jsonb),
  ('PA-STAFFING-ALR-2010', 'sairncare_compliance_seed.json', '{"data": {"_corrected": "The working summary said ''>=75% of hours from direct-care staff''. The rule says something different and materially so: at least 75% of the required service hours must be available DURING WAKING HOURS. It is a scheduling constraint on when the hours land, not a constraint on who provides them. Encoding it as a staffing-mix rule would check the wrong thing entirely and would pass a residence that concentrated its care hours overnight.", "always_present": "At all times one or more residents are present in the residence, a direct care staff person who is 21 years of age or older shall be present. The direct care staff person may be the administrator if the administrator provides direct care services.", "authority": {"citation": "55 Pa. Code §§ 2800.57, 2800.58, 2800.59, 2800.238", "quote": "(b) Direct care staff persons shall be available to provide at least 1 hour per day of assisted living services to each mobile resident. (c) Direct care staff persons shall be available to provide at least 2 hours per day of assisted living services to each resident who has mobility needs. (d) At least 75% of the assisted living service hours specified in subsections (b) and (c) shall be available during waking hours. ... Each resident in a special care unit shall be considered to be a resident with mobility needs under § 2800.57(c).", "read_on": "2026-08-22", "url": "https://www.pa.gov/content/dam/copapwp-pagov/en/dhs/documents/providers/clearances-and-licensing/documents/app-hsl/Assisted-Living-Residences-2800-Regulations.pdf"}, "awake_requirement": "Direct care staff persons on duty in the residence shall be awake at all times.", "hours_per_resident_per_day": [{"hours": 1, "resident_type": "mobile"}, {"hours": 2, "resident_type": "mobility_needs"}], "label": "Pennsylvania — Assisted Living Residence direct care staffing (service hours, not headcount ratio)", "method": "service_hours_per_resident_per_day", "multiple_buildings": "For a residence with multiple buildings on the same premises, regardless of distance, the direct care staffing requirements apply at all times residents are present.", "scu_mobility_rule": "Each resident in a special care unit shall be considered to be a resident with mobility needs, and therefore generates the 2-hour rate regardless of actual mobility.", "waking_hours_minimum_percent": 75}, "effective_from": "2010-10-01", "effective_to": null, "facility_class": "alr", "requirement_type": "staffing", "state": "PA", "status": "active"}'::jsonb),
  ('PA-STAFFING-PCH-2600', 'sairncare_compliance_seed.json', '{"data": {"_corrected": "The working summary recorded in unverified_notes said PCH has ''no numeric ratio'' and ''1 awake staff for 16+ residents''. BOTH ARE WRONG, and in opposite directions. (1) § 2600.57 is not ratio-free: it carries the same service-hours figures as the ALR chapter — 1 hour per day per mobile resident, 2 hours per day per resident with mobility needs, 75% of those hours during waking hours. Treating PCH as having no measurable requirement would have let a home under-staff with the app reporting nothing to check. (2) The awake rule is stricter than ''1 awake staff'', not looser: at 16 or more residents § 2600.58(a) requires that ALL direct care staff on duty be awake, not one of them. The ''one awake staff person'' figure belongs to § 2600.58(b), which applies to a home serving one or more but FEWER THAN 16 residents WITH MOBILITY NEEDS — a different trigger (mobility-needs count, not total census) as well as a different number. Encoding the summary would have produced a confident wrong answer for every home of 16 or more.", "additional_staffing": "§ 2600.60: staffing shall meet the needs identified in each resident''s assessment and support plan, and the Department may require additional staffing based on that plan, the design and construction of the home, and its operation and management. There is no formula for this — it is a discretionary overlay on top of the hours above.", "always_present": "At all times one or more residents are present in the home, a direct care staff person who is 21 years of age or older and who serves as the designee shall be present in the home. The direct care staff person may be the administrator if the administrator provides direct care services.", "authority": {"citation": "55 Pa. Code §§ 2600.57, 2600.58, 2600.59, 2600.60, 2600.63(a), 2600.238, adopted eff. October 24, 2005", "quote": "§ 2600.57: (b) Direct care staff persons shall be available to provide at least 1 hour per day of personal care services to each mobile resident. (c) Direct care staff persons shall be available to provide at least 2 hours per day of personal care services to each resident who has mobility needs. (d) At least 75% of the personal care service hours specified in subsections (b) and (c) shall be available during waking hours. ... § 2600.58: (a) If a home serves 16 or more residents, all direct care staff persons on duty in the home shall be awake at all times one or more residents are present in the home. (b) If a home serves one or more but less than 16 residents with mobility needs, at least one direct care staff person shall be awake at all times residents are present in the home. ... § 2600.238: Each resident in a secured dementia care unit shall be considered to be a resident with mobility needs under § 2600.57(c).", "read_on": "2026-08-23", "url": "https://www.pacodeandbulletin.gov/Display/pacode?file=/secure/pacode/data/055/chapter2600/s2600.57.html"}, "awake_requirement": "Conditional, and the condition differs by which test is met. (a) If the home serves 16 or more residents, ALL direct care staff persons on duty shall be awake at all times one or more residents are present. (b) If the home serves one or more but fewer than 16 residents WITH MOBILITY NEEDS, at least one direct care staff person shall be awake at all times residents are present.", "awake_rule_is_conditional": true, "awake_rule_note": "Reported as text rather than evaluated. This engine does not compute which branch applies, because doing so needs both the total census and the mobility-needs count at the moment in question, and a wrong branch here is a real staffing violation either way. Read both branches against the home''s actual numbers.", "first_aid_cpr_coverage": "At least one staff person for every 50 residents, trained in first aid and certified in obstructed airway techniques and CPR, shall be present in the home at all times (§ 2600.63(a)). Licensed, certified and registered medical personnel meet this and are exempt from the training requirement.", "hours_per_resident_per_day": [{"hours": 1, "resident_type": "mobile"}, {"hours": 2, "resident_type": "mobility_needs"}], "label": "Pennsylvania — Personal Care Home direct care staffing (service hours, not headcount ratio)", "method": "service_hours_per_resident_per_day", "multiple_buildings": "For a home with multiple buildings on the same premises within 300 feet of one another, the § 2600.57 direct care staff person shall be on the premises and available by two-way communication at all times one, two or three MOBILE residents are present. Regardless of distance between buildings, the full § 2600.57 requirements apply at all times four or more mobile residents, or one or more residents with mobility needs, are present.", "scu_mobility_rule": "Each resident in a secured dementia care unit shall be considered to be a resident with mobility needs under § 2600.57(c), and therefore generates the 2-hour rate regardless of actual mobility.", "waking_hours_minimum_percent": 75}, "effective_from": "2005-10-24", "effective_to": null, "facility_class": "pch", "requirement_type": "staffing", "state": "PA", "status": "active"}'::jsonb),
  ('PA-TRAINING-ALR-2010', 'sairncare_compliance_seed.json', '{"data": {"_corrected": "The working summary listed one dementia tier (4 hours initial, 2 hours annually) and missed that a SPECIAL CARE UNIT carries a materially higher, separate requirement: 8 hours initial within 30 days of hire plus 8 hours annually, on top of the 16-hour general annual training. A residence running an SCU on the 4+2 figure would be under-trained against the rule that actually applies to it. The 4+2 tier is real, but it is the baseline for all ALR staff, not the SCU standard. Also corrected: the 4 hours is due within 30 days of HIRE; it is the 18-hour general training that gates unsupervised work.", "authority": {"citation": "55 Pa. Code §§ 2800.65(c), 2800.65(g), 2800.65(h), 2800.69, 2800.236", "quote": "(g) Direct care staff persons may not provide unsupervised assisted living services until completion of 18 hours of training ... (h) Direct care staff persons shall have at least 16 hours of annual training relating to their job duties. The training required in § 2800.69 ... shall be in addition to the 16 hour annual training. ... § 2800.69: Administrative staff, direct care staff persons, ancillary staff persons, substitute personnel and volunteers shall receive at least 4 hours of dementia-specific training within 30 days of hire and at least 2 hours of dementia-specific training annually thereafter in addition to the training requirements of this chapter. ... § 2800.236: Each direct care staff person working in a special care unit for residents with Alzheimer''s disease or dementia shall have 8 hours of initial training within the first 30 days of the date of hire and a minimum of 8 hours of annual training related to dementia care and services, in addition to the 16 hours of annual training specified in § 2800.65.", "read_on": "2026-08-22", "url": "https://www.pa.gov/content/dam/copapwp-pagov/en/dhs/documents/providers/clearances-and-licensing/documents/app-hsl/Assisted-Living-Residences-2800-Regulations.pdf"}, "label": "Pennsylvania — Assisted Living Residence training, including the higher special-care-unit tier", "prior_to_first_workday": "Orientation in general fire safety and emergency preparedness, plus first aid and CPR certification before providing direct care.", "requirements": [{"gate": "may not provide unsupervised assisted living services until completion", "includes": ["training that includes a demonstration of job duties, followed by supervised practice", "successful completion and passing of the Department-approved direct care training course and competency test"], "initial_hours": 18, "who": "direct care staff — before providing UNSUPERVISED assisted living services"}, {"annual_hours": 16, "who": "direct care staff — general annual"}, {"annual_hours": 24, "who": "administrator — general annual"}, {"additive": true, "annual_hours": 2, "initial_deadline": "within 30 days of hire", "initial_hours": 4, "note": "in addition to the other training requirements of the chapter", "stacking": "additive", "who": "all staff (administrative, direct care, ancillary, substitute personnel, volunteers) — dementia baseline"}, {"additive": true, "annual_hours": 8, "initial_deadline": "within the first 30 days of the date of hire", "initial_hours": 8, "note": "in addition to the 16 hours of annual training specified in § 2800.65", "stacking": "additive", "who": "direct care staff working in a special care unit for residents with Alzheimer''s disease or dementia"}], "structure": "pre_unsupervised_hours_plus_additive_annual"}, "effective_from": "2010-10-01", "effective_to": null, "facility_class": "alr", "requirement_type": "training", "state": "PA", "status": "active"}'::jsonb),
  ('PA-TRAINING-PCH-2600', 'sairncare_compliance_seed.json', '{"data": {"_corrected": "Two corrections to the working summary. (1) It said ''12 hrs/yr general + 6 hrs/yr dementia'' as though both applied to every direct care staff person. The 12 is right (§ 2600.65(e)); the 6 is NOT a general requirement — § 2600.236 gives it only to direct care staff WORKING IN A SECURED DEMENTIA CARE UNIT, additive to the 12. A home with no secured unit that trained everyone to 18 hours would be over-reading the rule; a home WITH one that trained its unit staff to 12 would be under it. (2) Chapter 2600 has NO all-staff dementia-training requirement analogous to the ALR chapter''s § 2800.69 (4 hours within 30 days of hire plus 2 annually). That absence was checked by reading the whole staffing subchapter §§ 2600.51—2600.68, not inferred; the chapter simply has no § 2600.69. Carrying the ALR 4+2 across would invent a mandate. SEPARATELY: unlike the ALR chapter, PCH sets NO numeric hour figure for the pre-unsupervised gate. § 2800.65(g) says 18 hours; § 2600.65(d) says a Department-approved course plus a passing competency test with no hours attached. An hour number must not be shown here.", "annual_all_staff_topics": ["fire safety, delivered by a fire safety expert or by a staff person trained by one", "emergency preparedness procedures and recognition of and response to crises and emergencies", "resident rights", "the Older Adult Protective Services Act", "falls and accident prevention", "new population groups being served that were not previously served"], "authority": {"citation": "55 Pa. Code §§ 2600.64(a)—(c), 2600.65(a)—(h), 2600.236; §§ 2600.64 and 2600.65 amended June 17, 2016, effective June 18, 2016, 46 Pa.B. 3177", "quote": "§ 2600.65(d): Direct care staff persons hired after April 24, 2006, may not provide unsupervised ADL services until completion of the following: (1) Training that includes a demonstration of job duties, followed by supervised practice. (2) Successful completion and passing the Department-approved direct care training course and passing of the competency test. ... (e) Direct care staff persons shall have at least 12 hours of annual training relating to their job duties. (1) Staff person orientation shall be included in the 12 hours of training for the first year of employment. (2) On the job training for direct care staff persons may count for 6 out of the 12 training hours required annually. ... § 2600.64(c): An administrator shall have at least 24 hours of annual training relating to the job duties. ... § 2600.236: Each direct care staff person working in a secured dementia care unit shall have 6 hours of annual training related to dementia care and services, in addition to the 12 hours of annual training specified in § 2600.65.", "read_on": "2026-08-23", "url": "https://www.pacodeandbulletin.gov/Display/pacode?file=/secure/pacode/data/055/chapter2600/s2600.65.html"}, "label": "Pennsylvania — Personal Care Home training: a course-and-competency gate, not an hour count, plus annual hours", "no_general_dementia_requirement": true, "no_general_dementia_requirement_note": "Chapter 2600 contains no all-staff dementia-training mandate. Dementia care IS a required topic inside the initial direct care training (§ 2600.65(d)(3)(iv)) and inside the annual training topics (§ 2600.65(f)(3)), but with no separate hour allocation. Only secured-unit staff carry separate dementia hours.", "prior_to_first_workday": "Orientation in general fire safety and emergency preparedness (evacuation procedures, duties during drills and evacuation, meeting place, smoking safety, extinguisher location and use, smoke detectors and alarms, telephone use and notification of emergency services) for all direct care, ancillary, substitute personnel and volunteers.", "requirements": [{"gate": "may not provide unsupervised ADL services until completion", "includes": ["training that includes a demonstration of job duties, followed by supervised practice", "successful completion and passing of the Department-approved direct care training course and the competency test", "initial direct care staff person training across the 16 topics listed in § 2600.65(d)(3)"], "initial_hours": null, "no_hour_figure_note": "Chapter 2600 attaches no hour count to this gate. The ALR chapter''s 18 hours is a Chapter 2800 figure and does not apply here.", "reciprocity": "If the staff person completed the required initial direct care training within the past year at another home and provides written verification, the initial-training requirement does not apply again.", "who": "direct care staff hired after April 24, 2006 — before providing UNSUPERVISED ADL services"}, {"annual_hours": 12, "counting_rules": ["Staff orientation counts toward the 12 hours in the first year of employment.", "On-the-job training may count for at most 6 of the 12 hours required annually."], "who": "direct care staff — general annual"}, {"annual_hours": 24, "note": "The Department-approved administrator training course fulfils the annual requirement for the first year.", "who": "administrator — general annual"}, {"exemption": "Does not apply to an administrator hired or promoted prior to October 24, 2005.", "gate": "a Department-approved orientation, a 100-hour standardized Department-approved administrator training course, and a Department-approved competency-based test with a passing score", "initial_hours": 100, "who": "administrator — before initial employment"}, {"additive": true, "annual_hours": 6, "note": "in addition to the 12 hours of annual training specified in § 2600.65. § 2600.236 sets no initial-hours figure for the unit — contrast the ALR chapter''s 8 initial hours within 30 days of hire.", "stacking": "additive", "who": "direct care staff working in a secured dementia care unit"}], "scope_limit": "Only 55 Pa. Code Chapter 2600 was read for this rule. Requirements arising outside Title 55 Chapter 2600 — statutes, Department bulletins or licensing conditions — were not surveyed and are not represented here.", "structure": "course_and_competency_gate_plus_additive_annual", "within_40_scheduled_working_hours": "Orientation covering resident rights, the emergency medical plan, mandatory abuse and neglect reporting under the Older Adult Protective Services Act, and reporting of reportable incidents and conditions."}, "effective_from": "2016-06-18", "effective_to": null, "facility_class": "pch", "requirement_type": "training", "state": "PA", "status": "active"}'::jsonb)
),
licences as (
  select k.key, encode(digest(k.key,'sha256'),'hex') as h
  from public.license_keys k where k.app_id = 'sairncare'
),
live as (
  select l.key as licence, r.rule_id as rule_id,
         (to_jsonb(r) - 'id' - 'license_hash' - 'app_id' - 'created_at' - 'updated_at' - 'verified_by' - 'rule_id') as compute
  from licences l
  join public.alf_compliance_rules r on r.license_hash = l.h
),
-- every (licence, seed rule) PAIR. Joining expected straight to live on
-- rule_id alone cannot see "missing from licence A while present on licence B".
wanted as (
  select l.key as licence, x.rule_id, x.seed_file, x.compute
  from licences l cross join expected x
)
select
  coalesce(w.licence, v.licence)   as licence,
  coalesce(w.rule_id, v.rule_id)   as rule_id,
  w.seed_file,
  case
    when v.rule_id is null then 'MISSING -- seed rule never loaded onto this licence'
    when w.rule_id is null then 'ORPHAN -- live row with no seed; origin unknown'
    else 'STALE -- live content differs from the seed'
  end                              as verdict,
  jsonb_pretty(w.compute)          as seed_compute,
  jsonb_pretty(v.compute)          as live_compute
from wanted w
full outer join live v on v.licence = w.licence and v.rule_id = w.rule_id
where v.rule_id is null or w.rule_id is null
   or v.compute is distinct from w.compute
order by 4, 1, 2;
